/* Offline resource-only capture. Pinned USA translated procedures decode the
 * supplied fan-ROM resources; this is NOT a runtime ROM/gameplay replacement,
 * nor a claim that every fan-ROM machine-code patch was executed. */
#define GENESIS_NO_MAIN
#include "../.local/source/build/dune-base.c"
#include "em_web_world_intent.h"
#include "em_web_campaign.h"
#include <sys/stat.h>
static CPU c;static DuneMouse mouse;static uint8_t supplied_rom[1048576];static const char*out;static FILE*index_file;
static const unsigned frames[33]={300,600,1200,1500,1800,2700,3000,3600,3900,4200,4800,5100,5400,6000,6300,6600,7200,7500,7800,8700,9300,9600,9900,10500,10800,11100,11700,12000,12300,12900,13200,13500,13980};
static void check(int ok,const char*m){if(ok)return;fprintf(stderr,"FAIL %s pc=%06x fault=%d %s\n",m,c.pc,c.fault,c.reason?c.reason:"");exit(1);}
static void capture(unsigned index,unsigned rel){char path[4096];snprintf(path,sizeof path,"%s/card-%02u.rgb",out,index);FILE*f=fopen(path,"wb");check(f&&fwrite(c.vdp.frame,1,320*224*3,f)==320*224*3,"full original RGB capture");fclose(f);fprintf(index_file,"{\"index\":%u,\"relativeFrame\":%u,\"nativeFrame\":%llu,\"pc\":%u,\"scriptPointer\":%u,\"context\":%d}\n",index,rel,(unsigned long long)c.vdp.frames,c.pc,c.a[2],dune_mouse_context(&c));fflush(index_file);}
static void step(void){if(!em_web_campaign_observe(&c))dune_mouse_observe(&mouse,&c);machine_step(&c);check(!c.fault,"original resource decoder execution");}
int main(int argc,char**argv){check(argc==4,"usage FRONTEND.cpu.bin ROM.gen OUT_DIR");FILE*f=fopen(argv[1],"rb");check(f&&fread(&c,sizeof c,1,f)==1&&fgetc(f)==EOF,"original frontend fixture");fclose(f);f=fopen(argv[2],"rb");check(f&&fread(supplied_rom,sizeof supplied_rom,1,f)==1&&fgetc(f)==EOF,"supplied one-MiB resource ROM");fclose(f);c.rom=supplied_rom;c.rom_size=sizeof supplied_rom;c.reason=NULL;c.fault=0;c.audio_mode=AUDIO_MUTE;memset(c.pad_buttons,0,sizeof c.pad_buttons);memset(&mouse,0,sizeof mouse);mouse.enabled=1;memset(&em_web_campaign,0,sizeof em_web_campaign);em_web_campaign_after_load(&c);out=argv[3];mkdir(out,0755);char path[4096];snprintf(path,sizeof path,"%s/captures.jsonl",out);index_file=fopen(path,"w");check(index_file!=NULL,"capture index");check(em_web_campaign_route_request(&c,2),"original Tutorial route");uint64_t end=c.vdp.frames+3000;while(em_web_campaign.route_pending&&c.vdp.frames<end)step();check(!em_web_campaign.route_pending&&em_web_campaign.scene&&!strcmp(em_web_campaign.scene,"tutorial"),"original tutorial reached with supplied resource data");uint64_t start=c.vdp.frames,last=c.vdp.rendered_frames;unsigned at=0;while(at<33&&c.vdp.frames<start+16000){step();if(c.vdp.rendered_frames!=last){last=c.vdp.rendered_frames;unsigned rel=(unsigned)(c.vdp.frames-start);if(rel==frames[at]){capture(at,rel);at++;}}}check(at==33,"all33 description resource frames captured");fclose(index_file);puts("PASS all33 original tutorial resource compositions; no map/gameplay simulation or runtime patches");return 0;}
